-- --------------------------------------------------------

--
-- Table structure for table `sms_log`
--

CREATE TABLE `sms_log` (
  `id` int(11) NOT NULL,
  `student_id` int(11) NOT NULL,
  `phone` varchar(20) NOT NULL,
  `grade` int(11) NOT NULL,
  `term` varchar(20) NOT NULL,
  `year` int(11) NOT NULL,
  `exam_type` varchar(20) NOT NULL,
  `message` text NOT NULL,
  `status` varchar(20) NOT NULL,
  `provider_response` text DEFAULT NULL,
  `sent_at` datetime NOT NULL DEFAULT current_timestamp()
) ENGINE=MyISAM DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

-- --------------------------------------------------------

--
-- Table structure for table `Student`
--

CREATE TABLE `Student` (
  `id` int(11) NOT NULL,
  `UPI` varchar(100) NOT NULL,
  `Assesment` varchar(100) NOT NULL,
  `firstName` varchar(100) NOT NULL,
  `middleName` varchar(100) NOT NULL,
  `surname` varchar(100) NOT NULL,
  `parentName` varchar(150) DEFAULT NULL,
  `parentPhone` varchar(20) DEFAULT NULL,
  `birthNo` varchar(100) NOT NULL,
  `DOB` date DEFAULT NULL,
  `Grade` int(11) DEFAULT NULL,
  `password` varchar(255) DEFAULT 'student',
  `role` enum('user','admin','superadmin') DEFAULT 'user',
  `enrolStatus` enum('active','alumni') NOT NULL DEFAULT 'active',
  `gradYear` smallint(6) DEFAULT NULL,
  `gradAt` datetime DEFAULT NULL
) ENGINE=MyISAM DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;

